window.top_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

const mkBtn=(lbl,w,ht,fill,bord,tc)=>{
  fill=fill||0x1a3a0a;bord=bord||0x3a7a1a;tc=tc||'#90d040';
  const bg=new A();bg.beginFill(fill,1);bg.lineStyle(1,bord);bg.drawRoundedRect(0,0,w,ht,4);bg.endFill();
  const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:tc,align:'center'});
  t.anchor.set(0.5,0.5);t.x=w/2;t.y=ht/2;
  const c=new e();c.addChild(bg,t);c.interactive=true;c.buttonMode=true;
  c.on('mouseover',()=>bg.tint=0xddeecc);c.on('mouseout',()=>bg.tint=0xffffff);
  c._bg=bg;c._txt=t;return c;
};

// ── Таб категории ──────────────────────────────────────────────────
top_elements.lib.Top_tab=class extends e{
  constructor(lbl){
    super();
    this.bg=new A();this._draw(false);this.addChild(this.bg);
    const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#5a7a3a',align:'center'});
    t.anchor.set(0.5,0.5);t.x=148;t.y=18;this[t.name='lbl']=t;this.addChild(t);
    this.interactive=true;this.buttonMode=true;
    this.on('mouseover',()=>{if(!this._active)this.bg.tint=0xccddaa;});
    this.on('mouseout',()=>this.bg.tint=0xffffff);
  }
  _draw(active){
    this.bg.clear();
    if(active){this.bg.beginFill(0x1a3a0a,1);this.bg.lineStyle(1,0x4a9a1a);if(this.lbl)this.lbl.style.fill='#c8e040';}
    else{this.bg.beginFill(0x0a1608,0.9);this.bg.lineStyle(1,0x1e3c10,0.7);if(this.lbl)this.lbl.style.fill='#5a7a3a';}
    this.bg.drawRoundedRect(0,0,296,36,4);this.bg.endFill();
  }
  setActive(v){this._active=v;this._draw(v);}
};

// ── Строка игрока ──────────────────────────────────────────────────
top_elements.lib.Top_row=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg(false,false);this.addChild(this.bg_mc);
    // Место
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#8aaa50',align:'center'});pt.anchor.set(0.5,0.5);pt.x=36;pt.y=24;this[pt.name='place_txt']=pt;this.addChild(pt);
    // Медаль (топ-3)
    const mt=new z('',{fontFamily:'Arial',fontSize:22,align:'center'});mt.anchor.set(0.5,0.5);mt.x=36;mt.y=24;mt.visible=false;this[mt.name='medal_txt']=mt;this.addChild(mt);
    // Аватар-заглушка
    const av=new A();av.beginFill(0x1a3010,1);av.lineStyle(1,0x3a6020);av.drawRoundedRect(0,0,40,40,4);av.endFill();av.x=64;av.y=4;
    const avc=new z('👤',{fontFamily:'Arial',fontSize:20,align:'center'});avc.anchor.set(0.5,0.5);avc.x=84;avc.y=24;
    this.addChild(av,avc);
    // Имя
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#b8d840'});nt.x=116;nt.y=8;this[nt.name='name_txt']=nt;this.addChild(nt);
    // Статус / банда
    const st=new z('',{fontFamily:'Arial',fontSize:11,fill:'#5a7a3a'});st.x=116;st.y=28;this[st.name='sub_txt']=st;this.addChild(st);
    // Значение
    const vt=new z('',{fontFamily:'Southbank LT',fontSize:16,fontWeight:'bold',fill:'#c8a030',align:'right'});vt.anchor.set(1,0.5);vt.x=1150;vt.y=24;this[vt.name='value_txt']=vt;this.addChild(vt);
  }
  _drawBg(isMe,isTop){
    this.bg_mc.clear();
    if(isMe){this.bg_mc.beginFill(0x0e2208,0.97);this.bg_mc.lineStyle(2,0x3a7018,0.8);}
    else if(isTop){this.bg_mc.beginFill(0x0c1a06,0.95);this.bg_mc.lineStyle(1,0x2a5012,0.6);}
    else{this.bg_mc.beginFill(0x070d04,0.9);this.bg_mc.lineStyle(1,0x141e0a,0.5);}
    this.bg_mc.drawRoundedRect(0,0,1160,48,4);this.bg_mc.endFill();
  }
  setData(place, name, sub, value, isMe){
    const medals=['🥇','🥈','🥉'];
    if(place<=3){
      this.medal_txt.text=medals[place-1];this.medal_txt.visible=true;this.place_txt.visible=false;
    }else{
      this.place_txt.text='#'+place;this.place_txt.visible=true;this.medal_txt.visible=false;
    }
    this.name_txt.text=name;this.sub_txt.text=sub;this.value_txt.text=value;
    this._drawBg(isMe, place<=3);
    if(isMe){this.name_txt.style.fill='#e0f060';}else{this.name_txt.style.fill='#b8d840';}
  }
};

// ── Главное окно Топа ──────────────────────────────────────────────
top_elements.lib.Top_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x284a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x284a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('ТОП',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // 4 таба
    const tabs=new e();tabs.x=10;tabs.y=48;
    const tlabels=['⚔ УРОН','💰 МОНЕТЫ','🏆 БОССЫ','🥫 ТУШЁНКА'];
    for(let i=0;i<4;i++){
      const t=new top_elements.lib.Top_tab(tlabels[i]);t.x=i*(296+4);tabs['tab_'+i]=t;tabs.addChild(t);
    }
    this[tabs.name='tabs']=tabs;this.addChild(tabs);
    // Моё место
    const myt=new z('',{fontFamily:'Southbank LT',fontSize:12,fill:'#6a9a3a',align:'right'});myt.anchor.set(1,0.5);myt.x=1180;myt.y=62;this[myt.name='my_place_txt']=myt;this.addChild(myt);
    // Список строк (10 игроков)
    const list=new e();list.x=20;list.y=92;
    for(let i=0;i<10;i++){
      const r=new top_elements.lib.Top_row();r.x=0;r.y=i*52;list['row_'+i]=r;list.addChild(r);
    }
    this[list.name='row_list']=list;this.addChild(list);
    // Обновить кнопка
    const ref=mkBtn('↻ ОБНОВИТЬ',130,32,0x0e2208,0x3a6018,'#70b030');ref.x=1048;ref.y=48;this[ref.name='butt_refresh']=ref;this.addChild(ref);
  }
};

top_elements.lib.top_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new top_elements.lib.Top_win();this[b.name='top_win']=b;this.addChild(b);}
};
top_elements.stage=top_elements.lib.top_elements}};
